<div class="card"><h2>Video Queue</h2><form class="filters" method="get"><input type="hidden" name="page" value="videos"><select name="channel"><option value="">All channels</option><?php foreach($channels as $c):?><option value="<?=$c['id']?>" <?=(($_GET['channel']??'')==$c['id']?'selected':'')?>><?=e($c['channel_name'])?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><?php foreach(['Pending','Queued','Scheduled','Uploading','Uploaded','Failed','Retry'] as $s):?><option <?=$s===($_GET['status']??'')?'selected':''?>><?=$s?></option><?php endforeach;?></select><input name="q" placeholder="Search title/file" value="<?=e((string)($_GET['q']??''))?>"><button class="btn">Filter</button></form><table><tr><th>Video</th><th>Channel</th><th>Status</th><th>Schedule (UTC)</th><th>Actions</th></tr><?php foreach($videos as $v):?><tr><td><b><?=e($v['title'])?></b><div class="muted"><?=e($v['drive_file_name'])?></div></td><td><?=e($v['channel_name'])?></td><td><span class="badge"><?=e($v['status'])?></span><?php if($v['last_error']):?><div class="error-text"><?=e($v['last_error'])?></div><?php endif;?></td><td><?=e($v['scheduled_at']??'Not assigned')?></td><td><details><summary>Edit</summary><form method="post" class="stack"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="id" value="<?=$v['id']?>"><label>Title<input name="title" value="<?=e($v['title'])?>" required></label><label>Description<textarea name="description" rows="5"><?=e($v['description'])?></textarea></label><label>Tags<input name="tags" value="<?=e(implode(', ',json_decode($v['tags_json']??'[]',true)?:[]))?>"></label><label>Hashtags<input name="hashtags" value="<?=e(implode(', ',json_decode($v['hashtags_json']??'[]',true)?:[]))?>"></label><label>Category ID<input name="category_id" value="<?=e($v['category_id'])?>"></label><label>Privacy<select name="privacy_status"><?php foreach(['private','public','unlisted'] as $p):?><option value="<?=$p?>" <?=$v['privacy_status']===$p?'selected':''?>><?=$p?></option><?php endforeach;?></select></label><label><input type="checkbox" name="made_for_kids" value="1" <?=$v['made_for_kids']?'checked':''?>> Made for kids</label><label>Manual schedule<input type="datetime-local" name="scheduled_at" value="<?=e($v['scheduled_at']?date('Y-m-d\TH:i',strtotime($v['scheduled_at'])):'')?>"></label><label>Schedule timezone<input name="scheduled_timezone" value="<?=e($v['scheduled_timezone']?:'UTC')?>"></label><button class="btn primary">Save video</button></form></details><?php if($v['status']==='Failed'):?><form class="inline" method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="retry"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="btn">Retry</button></form><?php endif;?><?php if($v['youtube_video_id']):?><a class="btn" target="_blank" rel="noopener" href="https://www.youtube.com/watch?v=<?=e($v['youtube_video_id'])?>">YouTube</a><?php endif;?><form class="inline" method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="btn danger">Cancel</button></form><form class="inline" method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="btn danger">Delete</button></form></td></tr><?php endforeach;?></table></div>
